var useWatchListStore = create()((set, get) => ({
	watchList: watchListStorage.getWatchList(),
	collections: watchListStorage.getCollections(),
	removeItem: (link) => {
		set({ watchList: watchListStorage.removeFromWatchList(link) });
	},
	addItem: (item) => {
		set({ watchList: watchListStorage.addToWatchList(item) });
	},
	setItemCollections: (item, ids) => {
		set({ watchList: watchListStorage.setItemCollections(item, ids) });
	},
	removeFromCollection: (links, collectionId) => {
		const existingIds = new Set(get().collections.map((c) => c.id));
		const targets = new Set(links);
		let watchList = watchListStorage.getWatchList();
		for (const item of watchList) {
			if (!targets.has(item.link)) continue;
			const ids = getItemCollectionIds(item, existingIds).filter((id) => id !== collectionId);
			watchList = watchListStorage.setItemCollections(item, ids);
		}
		set({ watchList });
	},
	createCollection: (draft) => {
		const now = Date.now();
		const collection = {
			id: createCollectionId(),
			name: draft.name.trim(),
			icon: draft.icon,
			color: draft.color,
			createdAt: now,
			updatedAt: now
		};
		set({ collections: watchListStorage.saveCollections([...watchListStorage.getCollections(), collection]) });
		return collection;
	},
	updateCollection: (id, draft) => {
		set({ collections: watchListStorage.saveCollections(watchListStorage.getCollections().map((c) => c.id === id ? {
			...c,
			name: draft.name.trim(),
			icon: draft.icon,
			color: draft.color,
			updatedAt: Date.now()
		} : c)) });
	},
	deleteCollection: (id) => {
		set(watchListStorage.deleteCollection(id));
	}
}));
