// src/lib/storage/sourceTokenStorage.ts
var TOKEN_PREFIX = "source_token_";
var sourceTokenStorage = {
	async getToken(author) {
		if (!author) return null;
		return mainStorage.getString(`${TOKEN_PREFIX}${author.toLowerCase()}`) || null;
	},
	async setToken(author, token) {
		if (!author) return;
		mainStorage.setString(`${TOKEN_PREFIX}${author.toLowerCase()}`, token.trim());
	},
	async deleteToken(author) {
		if (!author) return;
		mainStorage.delete(`${TOKEN_PREFIX}${author.toLowerCase()}`);
	}
};
